SELECT orders.channel, CASE WHEN orders.status IN ('COMPLETED', 'SHIPPED') THEN 'core' ELSE 'other' END AS status_group, ROUND(STDDEV(order_items.unit_price), 2) AS stddev_unit_price, AVG(order_items.quantity) AS avg_quantity FROM order_items JOIN products ON order_items.product_id = products.id LEFT JOIN orders ON order_items.order_id = orders.id GROUP BY orders.channel, CASE WHEN orders.status IN ('COMPLETED', 'SHIPPED') THEN 'core' ELSE 'other' END ORDER BY stddev_unit_price DESC, orders.channel ASC;
